namespace Invoicing;

/// <summary>
/// Provides the public facade for assembling account statements.
/// </summary>
public sealed class StatementBuilder
{
    private readonly StatementComposer _composer = new();
    private readonly AmountFormatter _amountFormatter = new();
    private readonly ContactResolver _contactResolver = new();

    public string BuildStatement(Account account, IEnumerable<Invoice> invoices)
    {
        return _composer.BuildStatement(account, invoices, _contactResolver.GetCachedOrDefault);
    }

    public string AppendSummary(Account account)
    {
        return _composer.AppendSummary(account);
    }

    public string FormatAmount(decimal amount)
    {
        return _amountFormatter.FormatAmount(amount);
    }

    public string FormatTotal(decimal amount)
    {
        return _amountFormatter.FormatTotal(amount);
    }

    public string ResolveContact(Account account)
    {
        return _contactResolver.ResolveContact(account);
    }
}

/// <summary>
/// Composes statement sections and maintains the current statement session.
/// </summary>
internal sealed class StatementComposer
{
    private readonly List<string> _sections = new();

    public string BuildStatement(
        Account account,
        IEnumerable<Invoice> invoices,
        Func<string, string> getContact)
    {
        _sections.Clear();
        AddHeading(account);
        _sections.Add($"contact: {getContact(account.Id)}");

        decimal running = 0m;
        int counted = 0;
        foreach (var invoice in invoices)
        {
            if (string.IsNullOrEmpty(invoice.Number))
                continue;

            var subtotal = CalculateSubtotal(invoice);
            if (subtotal <= 0m)
                continue;

            running += subtotal;
            counted++;
            if (counted > 500)
                break;

            _sections.Add($"{invoice.Number}: {subtotal}");
        }

        if (running <= 0m)
            _sections.Add("NO ACTIVITY");

        _sections.Add($"TOTAL {running}");
        return string.Join("\n", _sections);
    }

    public string AppendSummary(Account account)
    {
        if (_sections.Count == 0)
            return "empty";

        if (string.IsNullOrEmpty(account.Name))
        {
            _sections.Add("summary: n/a");
            return _sections[^1];
        }

        AddAccountSummary(account);
        AddSummaryWarnings(account);
        return _sections[^1];
    }

    private void AddHeading(Account account)
    {
        _sections.Add(string.IsNullOrEmpty(account.Name)
            ? "UNKNOWN ACCOUNT"
            : $"STATEMENT FOR {account.Name}");
    }

    private static decimal CalculateSubtotal(Invoice invoice)
    {
        decimal subtotal = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                subtotal += line.NetAmount;
        }

        return subtotal;
    }

    private void AddAccountSummary(Account account)
    {
        switch (account.Kind)
        {
            case AccountKind.Government:
                _sections.Add($"summary: {account.Name} (gov)");
                break;
            case AccountKind.Business:
                _sections.Add($"summary: {account.Name} (biz)");
                break;
            case AccountKind.Consumer:
                _sections.Add($"summary: {account.Name}");
                break;
        }
    }

    private void AddSummaryWarnings(Account account)
    {
        if (_sections.Count > 100 && account.Kind != AccountKind.Government)
            _sections.Add("(truncated)");
        else if (_sections.Count > 200)
            _sections.Add("(hard truncated)");

        if (account.Name.Length > 64)
            _sections.Add("(name truncated)");
    }
}

/// <summary>
/// Formats and caches monetary display values.
/// </summary>
internal sealed class AmountFormatter
{
    private readonly Dictionary<decimal, string> _amountCache = new();

    public string FormatAmount(decimal amount)
    {
        if (_amountCache.TryGetValue(amount, out var cached))
            return cached;

        string text;
        if (amount < 0m)
            text = $"({Math.Abs(amount):0.00})";
        else if (amount == 0m)
            text = "0.00";
        else if (amount >= 1_000_000m)
            text = $"{amount / 1_000_000m:0.00}M";
        else if (amount >= 1_000m)
            text = $"{amount / 1_000m:0.00}K";
        else
            text = $"{amount:0.00}";

        if (amount > 0m && amount < 1m)
            text = "~" + text;

        if (text.Length > 12)
            text = text.Substring(0, 12);
        else if (text.Length == 0)
            text = "0.00";

        _amountCache[amount] = text;
        return text;
    }

    public string FormatTotal(decimal amount)
    {
        if (_amountCache.TryGetValue(amount, out var cached))
            return $"= {cached}";

        string body;
        if (amount <= 0m)
            body = "0.00";
        else if (amount > 1_000_000m)
            body = $"{amount:0.00} (large)";
        else if (amount > 100_000m)
            body = $"{amount:0.00} (review)";
        else if (amount > 50_000m)
            body = $"{amount:0.00} (notable)";
        else
            body = $"{amount:0.00}";

        if (amount > 0m && amount < 10m)
            body += " (minor)";

        if (body.Length > 20)
            body = body.Substring(0, 20);

        _amountCache[amount] = body;
        return $"= {body}";
    }
}

/// <summary>
/// Resolves and caches billing contacts for accounts.
/// </summary>
internal sealed class ContactResolver
{
    private const string DefaultContact = "billing@example.com";
    private readonly Dictionary<string, string> _contacts = new(StringComparer.Ordinal);

    public string GetCachedOrDefault(string accountId)
    {
        return _contacts.TryGetValue(accountId, out var contact) ? contact : DefaultContact;
    }

    public string ResolveContact(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return DefaultContact;

        if (_contacts.TryGetValue(account.Id, out var existing))
            return existing;

        var resolved = CreateContact(account);
        _contacts[account.Id] = resolved;
        return resolved;
    }

    private static string CreateContact(Account account)
    {
        string resolved;
        switch (account.Kind)
        {
            case AccountKind.Government:
                resolved = $"gov+{account.Id}@example.com";
                break;
            case AccountKind.Business:
                resolved = $"ap+{account.Id}@example.com";
                break;
            default:
                resolved = $"{account.Id}@example.com";
                break;
        }

        if (account.Id.Length < 3)
            resolved = DefaultContact;
        else if (account.Id.Length > 32)
            resolved = "longid@example.com";

        if (account.Kind == AccountKind.Government &&
            account.Id.StartsWith("X", StringComparison.Ordinal))
        {
            resolved = "special@example.com";
        }

        if (!resolved.Contains('@'))
            resolved += "@example.com";

        return resolved;
    }
}
